from __future__ import annotations

import json
import os
import re
import uuid
from collections import Counter, defaultdict
from copy import deepcopy
from datetime import datetime, timezone
from pathlib import Path
from threading import RLock
from typing import Any, Dict, List, Optional

from fastapi import APIRouter, HTTPException, Query
from pydantic import BaseModel, Field


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _dump(model: BaseModel) -> Dict[str, Any]:
    if hasattr(model, "model_dump"):
        return model.model_dump(exclude_none=True)
    return model.dict(exclude_none=True)


class ScriptCreate(BaseModel):
    scene: str = Field(default="default", description="直播场景，如 welcome/price/benefit/after_sale")
    product_id: Optional[str] = Field(default=None, description="商品ID，空表示通用话术")
    intent: str = Field(default="generic", description="评论意图，如 ask_price/ask_stock/ask_coupon")
    title: str = ""
    text: str = Field(..., min_length=1)
    tags: List[str] = Field(default_factory=list)
    enabled: bool = True
    priority: int = 0
    meta: Dict[str, Any] = Field(default_factory=dict)


class ScriptUpdate(BaseModel):
    scene: Optional[str] = None
    product_id: Optional[str] = None
    intent: Optional[str] = None
    title: Optional[str] = None
    text: Optional[str] = None
    tags: Optional[List[str]] = None
    enabled: Optional[bool] = None
    priority: Optional[int] = None
    meta: Optional[Dict[str, Any]] = None


class RenderRequest(BaseModel):
    text: Optional[str] = None
    script_id: Optional[str] = None
    variables: Dict[str, Any] = Field(default_factory=dict)


class MatchRequest(BaseModel):
    scene: str = "default"
    product_id: Optional[str] = None
    intent: str = "generic"
    variables: Dict[str, Any] = Field(default_factory=dict)


class StatsEvent(BaseModel):
    event: str = Field(default="impression", description="impression/play/click/order/skip")
    value: int = 1
    meta: Dict[str, Any] = Field(default_factory=dict)


class ScriptTemplate:
    pattern = re.compile(r"\{([^{}]+)\}")
    aliases = {
        "商品名": "product_name",
        "商品名称": "product_name",
        "品名": "product_name",
        "价格": "price",
        "到手价": "price",
        "卖点": "selling_point",
        "核心卖点": "selling_point",
        "库存": "stock",
        "优惠": "coupon",
        "主播名": "anchor_name",
        "用户名": "user_name",
        "用户": "user_name",
    }

    @classmethod
    def render(cls, template: str, variables: Dict[str, Any]) -> str:
        data = dict(variables or {})
        for zh, en in cls.aliases.items():
            if zh not in data and en in data:
                data[zh] = data[en]
            if en not in data and zh in data:
                data[en] = data[zh]

        def replace(match: re.Match[str]) -> str:
            key = match.group(1).strip()
            value = data.get(key)
            if value is None:
                value = data.get(cls.aliases.get(key, key))
            return str(value) if value is not None else match.group(0)

        return cls.pattern.sub(replace, template)

    @classmethod
    def variables(cls, template: str) -> List[str]:
        return sorted({m.group(1).strip() for m in cls.pattern.finditer(template or "")})


class ScriptStore:
    def __init__(self, path: Optional[str] = None, max_events: int = 5000):
        default_path = Path("data") / "script_workbench" / "scripts.json"
        self.path = Path(path or os.getenv("PHS_SCRIPT_WORKBENCH_DB", default_path))
        self.max_events = max_events
        self.lock = RLock()
        self.data: Dict[str, Any] = {"scripts": [], "events": []}
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._load()

    def _load(self) -> None:
        if not self.path.exists():
            self._save()
            return
        try:
            self.data = json.loads(self.path.read_text(encoding="utf-8"))
            self.data.setdefault("scripts", [])
            self.data.setdefault("events", [])
        except Exception:
            backup = self.path.with_suffix(".corrupt.json")
            self.path.replace(backup)
            self.data = {"scripts": [], "events": []}
            self._save()

    def _save(self) -> None:
        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps(self.data, ensure_ascii=False, indent=2), encoding="utf-8")
        tmp.replace(self.path)

    def _find_index(self, script_id: str) -> int:
        for i, item in enumerate(self.data["scripts"]):
            if item.get("id") == script_id:
                return i
        return -1

    def list(
        self,
        scene: Optional[str] = None,
        product_id: Optional[str] = None,
        intent: Optional[str] = None,
        enabled: Optional[bool] = None,
        q: Optional[str] = None,
    ) -> List[Dict[str, Any]]:
        with self.lock:
            items = deepcopy(self.data["scripts"])
        if scene:
            items = [x for x in items if x.get("scene") == scene]
        if product_id is not None:
            items = [x for x in items if x.get("product_id") == product_id]
        if intent:
            items = [x for x in items if x.get("intent") == intent]
        if enabled is not None:
            items = [x for x in items if bool(x.get("enabled", True)) is enabled]
        if q:
            q_lower = q.lower()
            items = [
                x for x in items
                if q_lower in (x.get("title", "") + x.get("text", "") + " ".join(x.get("tags", []))).lower()
            ]
        return sorted(items, key=lambda x: (-int(x.get("priority", 0)), x.get("updated_at", "")), reverse=False)

    def get(self, script_id: str) -> Dict[str, Any]:
        with self.lock:
            idx = self._find_index(script_id)
            if idx < 0:
                raise KeyError(script_id)
            return deepcopy(self.data["scripts"][idx])

    def create(self, payload: ScriptCreate) -> Dict[str, Any]:
        item = _dump(payload)
        item["id"] = uuid.uuid4().hex
        item["variables"] = ScriptTemplate.variables(item.get("text", ""))
        item["stats"] = {"impression": 0, "play": 0, "click": 0, "order": 0, "skip": 0}
        item["created_at"] = _now()
        item["updated_at"] = item["created_at"]
        with self.lock:
            self.data["scripts"].append(item)
            self._save()
        return deepcopy(item)

    def update(self, script_id: str, payload: ScriptUpdate) -> Dict[str, Any]:
        patch = _dump(payload)
        with self.lock:
            idx = self._find_index(script_id)
            if idx < 0:
                raise KeyError(script_id)
            item = self.data["scripts"][idx]
            item.update(patch)
            if "text" in patch:
                item["variables"] = ScriptTemplate.variables(item.get("text", ""))
            item["updated_at"] = _now()
            self._save()
            return deepcopy(item)

    def delete(self, script_id: str) -> Dict[str, Any]:
        with self.lock:
            idx = self._find_index(script_id)
            if idx < 0:
                raise KeyError(script_id)
            item = self.data["scripts"].pop(idx)
            self._save()
            return deepcopy(item)

    def match(
        self,
        scene: str,
        product_id: Optional[str],
        intent: str,
        variables: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        scripts = self.list(enabled=True)
        scored: List[tuple[int, Dict[str, Any]]] = []
        for item in scripts:
            score = int(item.get("priority", 0))
            item_scene = item.get("scene") or "default"
            item_product = item.get("product_id")
            item_intent = item.get("intent") or "generic"

            if item_scene == scene:
                score += 30
            elif item_scene in ("default", "*"):
                score += 5
            else:
                continue

            if product_id and item_product == product_id:
                score += 40
            elif item_product in (None, "", "*"):
                score += 8
            else:
                continue

            if item_intent == intent:
                score += 50
            elif item_intent in ("generic", "*"):
                score += 10
            else:
                continue

            scored.append((score, item))

        if not scored:
            raise KeyError("no matched script")

        scored.sort(key=lambda x: (-x[0], x[1].get("updated_at", "")))
        selected = deepcopy(scored[0][1])
        selected["rendered_text"] = ScriptTemplate.render(selected.get("text", ""), variables or {})
        selected["match_score"] = scored[0][0]
        return selected


class ScriptAnalytics:
    valid_events = {"impression", "play", "click", "order", "skip"}

    def __init__(self, store: ScriptStore):
        self.store = store

    def record(self, script_id: str, event: str, value: int = 1, meta: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        event = event.strip().lower()
        if event not in self.valid_events:
            raise ValueError(f"invalid event: {event}")
        value = max(1, int(value))

        with self.store.lock:
            idx = self.store._find_index(script_id)
            if idx < 0:
                raise KeyError(script_id)
            script = self.store.data["scripts"][idx]
            script.setdefault("stats", {})
            script["stats"][event] = int(script["stats"].get(event, 0)) + value
            script["updated_at"] = _now()

            row = {
                "id": uuid.uuid4().hex,
                "script_id": script_id,
                "event": event,
                "value": value,
                "meta": meta or {},
                "created_at": _now(),
            }
            self.store.data["events"].append(row)
            self.store.data["events"] = self.store.data["events"][-self.store.max_events:]
            self.store._save()
            return deepcopy(row)

    def summary(self) -> Dict[str, Any]:
        with self.store.lock:
            scripts = deepcopy(self.store.data["scripts"])
            events = deepcopy(self.store.data["events"])

        totals: Dict[str, int] = defaultdict(int)
        by_scene: Counter[str] = Counter()
        by_intent: Counter[str] = Counter()
        top_scripts = []

        for script in scripts:
            stats = script.get("stats", {})
            for k in self.valid_events:
                totals[k] += int(stats.get(k, 0))
            by_scene[script.get("scene", "default")] += 1
            by_intent[script.get("intent", "generic")] += 1
            top_scripts.append({
                "id": script.get("id"),
                "title": script.get("title"),
                "scene": script.get("scene"),
                "product_id": script.get("product_id"),
                "intent": script.get("intent"),
                "stats": stats,
                "score": int(stats.get("play", 0)) + int(stats.get("click", 0)) * 3 + int(stats.get("order", 0)) * 10,
            })

        top_scripts.sort(key=lambda x: x["score"], reverse=True)
        return {
            "script_count": len(scripts),
            "enabled_count": sum(1 for x in scripts if x.get("enabled", True)),
            "event_count": len(events),
            "totals": dict(totals),
            "by_scene": dict(by_scene),
            "by_intent": dict(by_intent),
            "top_scripts": top_scripts[:20],
        }


def create_script_workbench_router(
    store: Optional[ScriptStore] = None,
    prefix: str = "",
) -> APIRouter:
    script_store = store or ScriptStore()
    analytics = ScriptAnalytics(script_store)
    router = APIRouter(prefix=prefix, tags=["script-workbench"])

    @router.get("/scripts")
    def list_scripts(
        scene: Optional[str] = None,
        product_id: Optional[str] = None,
        intent: Optional[str] = None,
        enabled: Optional[bool] = Query(default=None),
        q: Optional[str] = None,
    ) -> Dict[str, Any]:
        items = script_store.list(scene=scene, product_id=product_id, intent=intent, enabled=enabled, q=q)
        return {"items": items, "count": len(items)}

    @router.post("/scripts")
    def create_script(payload: ScriptCreate) -> Dict[str, Any]:
        return script_store.create(payload)

    @router.get("/scripts/stats")
    def get_stats() -> Dict[str, Any]:
        return analytics.summary()

    @router.post("/scripts/render")
    def render_script(payload: RenderRequest) -> Dict[str, Any]:
        if payload.script_id:
            try:
                script = script_store.get(payload.script_id)
            except KeyError:
                raise HTTPException(status_code=404, detail="script not found")
            text = script.get("text", "")
        else:
            text = payload.text or ""
        return {
            "text": text,
            "rendered_text": ScriptTemplate.render(text, payload.variables),
            "variables": ScriptTemplate.variables(text),
        }

    @router.post("/scripts/match")
    def match_script(payload: MatchRequest) -> Dict[str, Any]:
        try:
            item = script_store.match(payload.scene, payload.product_id, payload.intent, payload.variables)
            analytics.record(item["id"], "impression", 1, {"source": "match"})
            return item
        except KeyError:
            raise HTTPException(status_code=404, detail="no matched script")

    @router.get("/scripts/{script_id}")
    def get_script(script_id: str) -> Dict[str, Any]:
        try:
            return script_store.get(script_id)
        except KeyError:
            raise HTTPException(status_code=404, detail="script not found")

    @router.put("/scripts/{script_id}")
    def update_script(script_id: str, payload: ScriptUpdate) -> Dict[str, Any]:
        try:
            return script_store.update(script_id, payload)
        except KeyError:
            raise HTTPException(status_code=404, detail="script not found")

    @router.delete("/scripts/{script_id}")
    def delete_script(script_id: str) -> Dict[str, Any]:
        try:
            return {"deleted": True, "item": script_store.delete(script_id)}
        except KeyError:
            raise HTTPException(status_code=404, detail="script not found")

    @router.post("/scripts/{script_id}/stats")
    def record_script_stat(script_id: str, payload: StatsEvent) -> Dict[str, Any]:
        try:
            return analytics.record(script_id, payload.event, payload.value, payload.meta)
        except KeyError:
            raise HTTPException(status_code=404, detail="script not found")
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc))

    return router


class ScriptWorkbenchProvider:
    provider_id = "script_workbench"
    name = "Script Workbench"
    version = "0.1.0"

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self.store = ScriptStore(self.config.get("db_path"))
        self.analytics = ScriptAnalytics(self.store)
        self.router = create_script_workbench_router(self.store)

    def get_router(self) -> APIRouter:
        return self.router

    def health(self) -> Dict[str, Any]:
        return {
            "provider": self.provider_id,
            "ok": True,
            "db_path": str(self.store.path),
            "script_count": len(self.store.list()),
        }

    def metadata(self) -> Dict[str, Any]:
        return {
            "id": self.provider_id,
            "name": self.name,
            "version": self.version,
            "routes": ["/scripts", "/scripts/stats", "/scripts/match", "/scripts/render"],
        }


def create_provider(config: Optional[Dict[str, Any]] = None) -> ScriptWorkbenchProvider:
    return ScriptWorkbenchProvider(config)


